                    ]
                ),
            ],
        ];

        foreach ($data as &$row) {
            if ((int) $row['call_status'] === 1 && (int) $row['list_status'] === 1) {
                $rank = json_decode($row['rank'] ?? '[]', true);
                $total = 0;
                foreach ($rank ?? [] as $range) {
                    $start = (int) $range['start'];
                    $end   = (int) $range['end'];
                    $total += max(0, $end - $start + 1);
                }
                $row['total'] = (string) $total;
            }
        }

        unset($row);

        DB::table('calling_dla')->insert($data);
    }
}
